// PDF statements: the TypeScript port must extract exactly what Rails'
// PdfStatementExtractor extracts from the same page text. expected/pdf/*.json is
// generated by Ruby (see fixtures/README.md).
import { readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { Categorizer, checkPdfBytes, extractPdfStatement, ImportError, isPdf, pdfDraftToStatement, StatementYearResolver } from "../src";

const fixtures = join(__dirname, "../fixtures");
const json = (path: string) => JSON.parse(readFileSync(join(fixtures, path), "utf8"));
const codeOf = (run: () => unknown) => {
  try {
    run();
    return null;
  } catch (error) {
    if (error instanceof ImportError) return error.code;
    throw error;
  }
};

describe("Ruby parity: PDF extraction", () => {
  const files = readdirSync(join(fixtures, "pdf")).filter((name) => name.endsWith(".txt"));

  it("has fixtures", () => expect(files.length).toBeGreaterThanOrEqual(2));

  it.each(files)("%s", (file) => {
    const expected = json(`expected/pdf/${file.replace(/\.txt$/, ".json")}`);
    const pages = readFileSync(join(fixtures, "pdf", file), "utf8").split("\f");
    const { today, ...result } = expected;
    expect(extractPdfStatement(pages, { currency: "USD", today })).toEqual(result);
  });

  const errors: Array<{ name: string; pages: string[] }> = json("pdf/errors.json");
  const expectedErrors: { today: string; cases: Array<{ name: string; code: string | null }> } = json("expected/pdf/errors.json");
  it.each(errors)("error: $name", (item) => {
    const expected = expectedErrors.cases.find((candidate) => candidate.name === item.name)!;
    expect(codeOf(() => extractPdfStatement(item.pages, { currency: "USD", today: expectedErrors.today }))).toBe(expected.code);
  });
});

describe("PDF files", () => {
  const pdf = new TextEncoder().encode("%PDF-1.7\n...");

  it("recognizes PDFs by header or extension", () => {
    expect(isPdf(pdf, "statement.bin")).toBe(true);
    expect(isPdf(new Uint8Array([1, 2]), "Statement.PDF")).toBe(true);
    expect(isPdf(new TextEncoder().encode("Date,Amount"), "statement.csv")).toBe(false);
  });

  it("applies the Rails file checks", () => {
    expect(codeOf(() => checkPdfBytes(pdf, "statement.pdf"))).toBeNull();
    expect(codeOf(() => checkPdfBytes(pdf, "statement.csv"))).toBe("pdf_filename_limit");
    expect(codeOf(() => checkPdfBytes(pdf, `${"a".repeat(252)}.pdf`))).toBe("pdf_filename_limit");
    expect(codeOf(() => checkPdfBytes(new Uint8Array(), "statement.pdf"))).toBe("pdf_empty");
    expect(codeOf(() => checkPdfBytes(new Uint8Array(2 * 1024 * 1024 + 1).fill(0x25), "statement.pdf"))).toBe("pdf_size_limit");
    expect(codeOf(() => checkPdfBytes(new TextEncoder().encode("hello"), "statement.pdf"))).toBe("pdf_not_readable");
  });

  it("limits pages and text", () => {
    expect(codeOf(() => extractPdfStatement(Array(21).fill("2025-01-01 Coffee -1.00"), { currency: "USD" }))).toBe("pdf_page_limit");
    expect(codeOf(() => extractPdfStatement(["x".repeat(512 * 1024 + 1)], { currency: "USD" }))).toBe("pdf_text_limit");
    const rows = Array.from({ length: 501 }, () => "2025-01-01 Coffee -1.00").join("\n");
    expect(codeOf(() => extractPdfStatement([rows], { currency: "USD" }))).toBe("pdf_candidate_limit");
  });
});

describe("year resolver", () => {
  it("uses the statement period when it is labelled", () => {
    const resolver = new StatementYearResolver("Statement period: Dec 1, 2025 - Jan 15, 2026", "2026-11-09");
    expect(resolver.confident).toBe(true);
    expect(resolver.endDate).toBe("2026-01-15");
    expect(resolver.yearFor(12, 20)).toBe(2025);
    expect(resolver.yearFor(1, 3)).toBe(2026);
    expect(resolver.yearFor(2, 30)).toBeNull();
  });

  it("ignores far-future dates and falls back to today", () => {
    const resolver = new StatementYearResolver("Promotion ends 2031-01-01", "2026-11-09");
    expect(resolver.confident).toBe(false);
    expect(resolver.endDate).toBe("2026-11-09");
  });
});

describe("reviewed PDF rows to a statement", () => {
  const draft = { closingBalanceCents: 12345, closingBalanceOn: "2025-10-31" };
  const options = { currency: "USD" as const, categorizer: new Categorizer() };

  it("imports only the included rows, validated like a CSV", () => {
    const parsed = pdfDraftToStatement(draft, [
      { bookedOn: "2025-10-02", description: 'Payroll "ACME", Inc', amount: "+2400.00", include: true },
      { bookedOn: "2025-10-03", description: "Running balance", amount: "", include: false },
      { bookedOn: "2025-10-05", description: "Grocery Market", amount: "-86.35", include: true },
    ], options);
    expect(parsed.rows.map((row) => [row.bookedOn, row.description, row.amountCents])).toEqual([
      ["2025-10-02", 'Payroll "ACME", Inc', 240000],
      ["2025-10-05", "Grocery Market", -8635],
    ]);
    expect(parsed.closingBalanceCents).toBe(12345);
    expect(parsed.closingBalanceOn).toBe("2025-10-31");
  });

  it("refuses an empty selection and blank amounts", () => {
    expect(codeOf(() => pdfDraftToStatement(draft, [{ bookedOn: "2025-10-02", description: "A", amount: "-1.00", include: false }], options))).toBe("select_transaction");
    expect(codeOf(() => pdfDraftToStatement(draft, [{ bookedOn: "2025-10-02", description: "A", amount: "", include: true }], options))).toBe("row_invalid_money");
  });
});
